{
  "constraints": [
    {
      "constraint": "图像中必须出现至少一个可识别的雪佛兰品牌标识，且标识形式限于领结形图形标志、英文品牌名 Chevrolet 或中文品牌名雪佛兰。",
      "polarity": "must_have",
      "variants": [
        "领结形图形标志",
        "英文品牌名 Chevrolet",
        "中文品牌名雪佛兰"
      ],
      "source": "desc"
    },
    {
      "constraint": "图像中不得以盾形、圆形、椭圆、星形、马形等非领结轮廓图形作为雪佛兰品牌图形标识。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "图像中不得出现错误拼写的雪佛兰品牌名称（如 Chevrole、Chevrlet、Chevrolet 等）作为品牌标识。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像中不得将雪佛兰表现为非汽车/非乘用车品牌（如摩托车、自行车、飞机、火车等交通工具品牌）。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    }
  ]
}
